def find_sums_of_squares(limit):
    sums = set()
    # Iterate over x and y such that x >= 1, y >= x, and y <= limit
    for x in range(1, limit + 1):
        for y in range(x, limit + 1):
            if x != y:
                sums.add(x*x + y*y)

    sorted_sums = sorted(list(sums))
    return sorted_sums

