import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def generate_good_numbers(limit_d, limit_x0, limit_y0):
    good_numbers = set()

    # Step 1: Generate primitive sums m0 = x0^2 + y0^2
    primitive_sums = {}
    for x0 in range(1, limit_x0 + 1):
        for y0 in range(x0 + 1, limit_y0 + 1):
            if gcd(x0, y0) == 1:
                m0 = x0*x0 + y0*y0
                primitive_sums[m0] = (x0, y0)

    # Step 2: Generate multiples d^2 * m0
    for d in range(1, limit_d + 1):
        d_squared = d*d
        for m0 in primitive_sums:
            m = d_squared * m0
            good_numbers.add(m)

    return sorted(list(good_numbers))

# We need the 20th smallest number. Let's test limits.
# The 20th number is 208 = 4^2 * 13. So d needs to go up to at least 4.
# Primitive sum m0=13 requires (2, 3), so x0, y0 need to go up to at least 3.
# Let's try slightly larger bounds to ensure 20 is captured.
all_good_numbers = generate_good_numbers(limit_d=6, limit_x0=5, limit_y0=10)

print(f"Total numbers found: {len(all_good_numbers)}")
print("First 30 good numbers:")
print(all_good_numbers[:30])

# Check 20th smallest
if len(all_good_numbers) >= 20:
    print(f"\n20th smallest good number: {all_good_numbers[19]}")
else:
    print("\nNot enough numbers found with current limits.")

import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

good_numbers_gcd_one = []

x = 1
while len(good_numbers_gcd_one) < 20:
    y = x + 1
    while True:
        m = x*x + y*y

        # Check if we already added this value (though unlikely if we iterate systematically)
        if m not in good_numbers_gcd_one:
            if gcd(x, y) == 1:
                good_numbers_gcd_one.append(m)

        y += 1

        # Safety break to prevent infinite loops if the count never reaches 20
        if y > 100:
            break 

    x += 1

# Sort and select the 20th
good_numbers_gcd_one.sort()

if len(good_numbers_gcd_one) >= 20:
    print(f"The 20th smallest good number under the hypothesis gcd(x,y)=1 is: {good_numbers_gcd_one[19]}")
else:
    print("Could not find 20 numbers under the current search bounds.")

